/* From Uiverse.io by Juanes200122 - Tags: animation, social, card */
.__UIV_SCOPE__ .container {
  position: relative;
  max-width: 500px;
  width: 100%;
  background: #ececec;
  margin: 0 15px;
  padding: 10px 20px;
  border-radius: 7px;
}

.__UIV_SCOPE__ .container .skill-box {
  width: 100%;
  margin: 25px 0;
}

.__UIV_SCOPE__ .skill-box .title {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: #333;
}

.__UIV_SCOPE__ .skill-box .skill-bar {
  height: 8px;
  width: 100%;
  border-radius: 6px;
  margin-top: 6px;
  background: rgba(0,0,0,0.1);
}

.__UIV_SCOPE__ .skill-bar .skill-per {
  position: relative;
  display: block;
  height: 100%;
  width: 90%;
  border-radius: 6px;
  background: #4070f4;
  animation: progress 0.4s ease-in-out forwards;
  opacity: 0;
}

.__UIV_SCOPE__ .skill-per.html {
   /*progreso de las diferentes lenguajes*/
  width: 50%;
  animation-delay: 0.1s;
}

.__UIV_SCOPE__ .skill-per.css {
         /*progreso de las diferentes lenguajes*/
  width: 70%;
  animation-delay: 0.1s;
}

.__UIV_SCOPE__ .skill-per.javascript {
      /*progreso de las diferentes lenguajes*/
  width: 50%;
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .skill-per.nodejs {
      /*progreso de las diferentes lenguajes*/
  width: 30%;
  animation-delay: 0.3s;
}

@keyframes progress {
  0% {
    width: 0;
    opacity: 1;
  }

  100% {
    opacity: 1;
  }
}

.__UIV_SCOPE__ .skill-per .tooltip {
  position: absolute;
  right: -14px;
  top: -28px;
  font-size: 9px;
  font-weight: 500;
  color: #fff;
  padding: 2px 6px;
  border-radius: 3px;
  background: #4070f4;
  z-index: 1;
}

.__UIV_SCOPE__ .tooltip::before {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -2px;
  height: 10px;
  width: 10px;
  z-index: -1;
  background-color: #4070f4;
  transform: translateX(-50%) rotate(45deg);
}
